// Schedule kind identifiers.
const (
	scheduleKindRaw   = "raw"
	scheduleKindDrift = "drift"
	scheduleKindTTL   = "ttl"
)

// scheduleGetRenderFunc renders a single scheduled action.
type scheduleGetRenderFunc func(w io.Writer, schedule apitype.ScheduledAction) error

// scheduleListRenderFunc renders a list of scheduled actions.
type scheduleListRenderFunc func(w io.Writer, schedules []apitype.ScheduledAction) error

// scheduleSummary is a flattened, human-readable summary of a scheduled action.
// It is used as the JSON output shape for the list and get commands. The ID
// field is exported to allow JSON deserialization by tests.
type scheduleSummary struct {
	ID       string `json:"id"`
	Type     string `json:"type"`
	Settings string `json:"settings"`
	Schedule string `json:"schedule"`
	NextRun  string `json:"nextRun,omitempty"`
	LastRun  string `json:"lastRun,omitempty"`
	Created  string `json:"created,omitempty"`
}

// scheduleDefInfo captures the fields inferred from a scheduled action's
// deployment definition.
type scheduleDefInfo struct {
	op                 apitype.PulumiOperation
	deleteAfterDestroy bool
	autoRemediate      bool
}

// parseScheduleDefinition decodes the deployment definition embedded in a
// scheduled action, returning the operation and any relevant options.
func parseScheduleDefinition(s apitype.ScheduledAction) scheduleDefInfo {
	var info scheduleDefInfo
	if len(s.Definition) == 0 {
		return info
	}
	var def apitype.ScheduledDeploymentDefinition
	if err := json.Unmarshal(s.Definition, &def); err != nil || def.Request == nil {
		return info
	}
	info.op = def.Request.Op
	if def.Request.Operation != nil && def.Request.Operation.Options != nil {
		info.deleteAfterDestroy = def.Request.Operation.Options.DeleteAfterDestroy
		info.autoRemediate = def.Request.Operation.Options.RemediateIfDriftDetected
	}
	return info
}

// scheduleKindOf infers the schedule kind (raw, drift, or ttl) from the
// definition and timing fields of a scheduled action.
func scheduleKindOf(s apitype.ScheduledAction) string {
	info := parseScheduleDefinition(s)
	switch {
	case info.op == apitype.Destroy && s.ScheduleOnce != "":
		return scheduleKindTTL
	case info.op == apitype.DetectDrift:
		return scheduleKindDrift
	default:
		return scheduleKindRaw
	}
}

// scheduleScheduleString returns the human-readable schedule value: the cron
// expression for recurring schedules, or "Once" for one-time schedules.
func scheduleScheduleString(s apitype.ScheduledAction) string {
	if s.ScheduleCron != "" {
		return s.ScheduleCron
	}
	if s.ScheduleOnce != "" {
		return "Once"
	}
	return ""
}

// toScheduleSummary flattens a scheduled action into a scheduleSummary.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	info := parseScheduleDefinition(s)

	var typ, settings string
	switch {
	case info.op == apitype.Destroy && s.ScheduleOnce != "":
		typ = scheduleKindTTL
		if info.deleteAfterDestroy {
			settings = "destroy + delete stack"
		} else {
			settings = "destroy"
		}
	case info.op == apitype.DetectDrift:
		typ = scheduleKindDrift
		settings = "detect"
	default:
		typ = scheduleKindRaw
		settings = "pulumi " + string(info.op)
	}

	summary := scheduleSummary{
		ID:       s.ID,
		Type:     typ,
		Settings: settings,
		Schedule: scheduleScheduleString(s),
		NextRun:  s.NextExecution,
		Created:  s.Created,
	}
	if s.LastExecuted != nil {
		summary.LastRun = *s.LastExecuted
	}
	return summary
}

